def area(x):
    return x * (40 - 2 * x)

assert area(10) == 200
assert area(0) == 0 and area(20) == 0
assert 40 - 4 * 10 == 0

def f(x):
    return x ** 3 - 6 * x * x + 9 * x + 1

assert f(0) == 1 and f(1) == 5 and f(3) == 1 and f(4) == 5
assert 3 * (1 - 1) * (1 - 3) == 0

def box(x):
    return x * (12 - 2 * x) ** 2

assert box(2) == 128 and box(0) == 0 and box(6) == 0
print(area(10), f(1), box(2))
